import { describe, it, expect } from 'vitest';
import * as E from 'fp-ts/Either';
import { authenticate } from '../pipeline';

describe('Auth Pipeline', () => {
  it('returns Left for invalid credentials', async () => {
    const result = await authenticate({ username: 'bad', password: 'creds' })();
    expect(E.isLeft(result)).toBe(true);
    if (E.isLeft(result)) {
      expect(result.left.code).toBe('INVALID_CREDENTIALS');
    }
  });

  it('returns Left for expired tokens', async () => {
    const result = await authenticate({ username: 'expired', password: 'token' })();
    expect(E.isLeft(result)).toBe(true);
    if (E.isLeft(result)) {
      expect(result.left.code).toBe('TOKEN_EXPIRED');
    }
  });

  it('returns Right with session on success', async () => {
    const result = await authenticate({ username: 'valid', password: 'user' })();
    expect(E.isRight(result)).toBe(true);
    if (E.isRight(result)) {
      expect(result.right).toHaveProperty('token');
      expect(result.right).toHaveProperty('userId');
    }
  });

  it('handles MFA validation failure', async () => {
    const result = await authenticate({ username: 'mfa', password: 'pending' })();
    expect(E.isLeft(result)).toBe(true);
    if (E.isLeft(result)) {
      expect(result.left.code).toBe('MFA_REQUIRED');
    }
  });

  it('pipeline logs success metrics on completion', async () => {
    const result = await authenticate({ username: 'valid', password: 'user' })();
    expect(E.isRight(result)).toBe(true);
  });
});
